StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Analog Input Simple                                                                                                                                                                                                                                                                         
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE					SIGN								DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-04-22			William Veim					Initial release    
//	1.0.1				2025-05-02			Ruben Byman					Added state control for unique Liquiline statuses
// 1.0.2				2025-06-24			Jan Magne Dybvik			Added configuration for Alarm SMS Process value (Cfg_AlarmSMS_SignificantDigits and Cfg_AlarmSMS_UseUnitPrefix)
// 1.1.0				2025-09-08			Jan Magne Dybvik			Added option for custom unit using parameters Cfg_UseCustomUnit and Cfg_CustomUnit
//	1.2.0				2025-03-19			William Veim					Removed input for SMS process value 
//
//===============================================================================================================================
//
//		FUNKSJONALITET:
//		*Endress + Hauser Liquiline Analog Channel input
//		*Excecution of analog input logic
//
//===============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_AnalogValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

IF  NOT Ext_AnalogValue.INT_Data.Initialise THEN
	
	//Common parameters are initialised in logic block
	
	//State config
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Quality:=3; //Uncertain quality = Warning
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Alarm:=TRUE; //Uncertain quality = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_11.Cfg_Quality:=0; //Configuration error = Diagnostic
	Ext_AnalogValue.EXT_Engineering.StateCfg_11.Cfg_Alarm:=TRUE; //Configuration error= Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_12.Cfg_Quality:=1; //Device failiure = Equipment failiure
	Ext_AnalogValue.EXT_Engineering.StateCfg_12.Cfg_Alarm:=TRUE; //Device failiure = Alarm
	
	//Initialise set true in logic block
	
END_IF;

(*************************************************************************
 *	BLOCK SPESIFIC PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Cfg_ValueType:=TRUE; //INPUT VALUE TO LOGIC BLOCK IS PROCESS VALUE
FB_AnalogInput_Logic.Cfg_CalibrationEnable:=	FALSE;

(*************************************************************************
 *	UPDATE INPUT PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_AnalogInput_Logic.Inp_AlmSuppressDesc:=		Inp_AlmSuppressDesc;
FB_AnalogInput_Logic.Inp_Value:=							Inp_AnChannel.Value;
FB_AnalogInput_Logic.Inp_ModuleFault:=				Inp_EIP_Interface[Cfg_IP_Addr];

(*************************************************************************
 *	UPDATE CONFIG PARAMETERS
 *************************************************************************)
FB_AnalogInput_Logic.Cfg_SignalValue_Y0:=			0; //NOT IN USE
FB_AnalogInput_Logic.Cfg_SignalValue_Y1:=			0; //NOT IN USE
FB_AnalogInput_Logic.Cfg_SignalValue_Unit:=		''; //NOT IN USE
FB_AnalogInput_Logic.Cfg_ControlCabinet:=			Cfg_ConnCabinet;
FB_AnalogInput_Logic.Cfg_ControllerTAG:=			Cfg_ControllerName;
FB_AnalogInput_Logic.Cfg_ProcessTAG:=				Cfg_ProcessTAG;

// Select Unit from Liquiline or block parameter
IF Cfg_UseProcessValueUnit THEN
	FB_AnalogInput_Logic.Cfg_ProcessValue_Unit:=	Cfg_ProcessValue_Unit;
ELSE
	FB_AnalogInput_Logic.Cfg_ProcessValue_Unit:=	HE_Liquiline_AnUnit(Inp_AnChannel.EngUnit);
END_IF;

(*************************************************************************
 *	STATISTICS
 * (Asuming sensor has been changed, if serial number has changed)
 *************************************************************************)
 
TON_SensorFault(In:=Wrk_DevFail OR Wrk_Bad OR Wrk_Uncertain, PT:=TIME#2h);

FB_AnalogInput_Logic.Inp_RstOperatingTime:=TON_SensorFault.Q;

(*************************************************************************
 *	UPDATING STATE CONTROL PARAMTERS
 *************************************************************************)
 
 //STATE 1 - Locked to "Critical high limit"
 //STATE 2 - Locked to "Pre high limit"
 //STATE 3 - Locked to "Pre low limit"
 //STATE 4 - Locked to "Critical low limit"
 //STATE 5 - Locked to "Process value out of range"
 //STATE 6 - Locked to "Input module fault"
 //STATE 7 - Locked to "Value stuck"
 //STATE 8 - Locked to "Calibration fault"
 //STATE 9 - Locked to "Unstable value"

Wrk_Uncertain := 	Inp_AnChannel.Status = 64;
Wrk_Bad :=			 	(Inp_AnChannel.Status <> 128) AND (Inp_AnChannel.Status <> 64);
Wrk_ConfigError:=	Inp_AnChannel.Status = 4;
Wrk_DevFail:=			Inp_AnChannel.Status = 12;

FB_AnalogInput_Logic.Cfg_State10_InUse := 	TRUE;
FB_AnalogInput_Logic.Inp_State10_Desc :=	'Uncertain quality';
FB_AnalogInput_Logic.Inp_State10_State := 	Wrk_Uncertain;

FB_AnalogInput_Logic.Cfg_State11_InUse := 	TRUE;
FB_AnalogInput_Logic.Inp_State11_Desc :=	'Configuration Error';
FB_AnalogInput_Logic.Inp_State11_State :=	Wrk_ConfigError;

FB_AnalogInput_Logic.Cfg_State12_InUse := 	TRUE;
FB_AnalogInput_Logic.Inp_State12_Desc :=	'Device Failure';
FB_AnalogInput_Logic.Inp_State12_State :=	Wrk_DevFail;

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)
 
FB_AnalogInput_Logic(ENS:=TRUE, 
										Ext_AnalogValue:=	Ext_AnalogValue, 
										Int_Alarm:=				Int_Alarm); 

(*************************************************************************
 *	UPDATING FB OUTPUT
 *************************************************************************)
 
Sts_Alarm:= 								FB_AnalogInput_Logic.Sts_AlarmTriggered;
Out_ProcessValue:= 				Ext_AnalogValue.EXT_Operator.ProcessValue;
Out_ProcessValue_Percent := 	Ext_AnalogValue.EXT_Operator.ProcessValue_Percent;
